                                    <option value="admin">Make Admin</option>
                                  </>
                                )}
                              </select>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
               </div>
            </section>
          </div>
        )}
      </div>
    </div>
  );
};

