              <span className="mr-3 text-slate-400">:</span>
              <span className="flex-1 text-slate-700">{invoice.guest.phone || '-'}</span>
            </div>
          </div>
        </div>

        <div className="border border-slate-300 p-3 rounded-sm flex flex-col bg-slate-50/30">
          <h3 className="text-[7pt] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 pb-1.5 mb-3">STAY SUMMARY</h3>
          <div className="space-y-1.5 text-[9pt]">
            <div className="flex justify-between items-center border-b border-slate-100 pb-1 mb-1">
              <span className="text-[7pt] font-bold text-slate-400 uppercase">FOLIO NO.</span>
              <span className="font-mono font-bold text-indigo-600">{invoice.invoiceNumber}</span>
            </div>
            <div className="flex">
              <span className="w-24 shrink-0 font-bold text-slate-500 text-[8pt]">Room No.</span>
              <span className="mr-3 text-slate-400">:</span>
              <span className="flex-1 font-black text-slate-900">{invoice.stay.roomNumber}</span>
            </div>
            <div className="flex">
              <span className="w-24 shrink-0 font-bold text-slate-500 text-[8pt]">Arrival</span>
              <span className="mr-3 text-slate-400">:</span>
              <span className="flex-1 font-bold text-slate-900">{formatIndonesianDate(invoice.stay.checkIn)}</span>
            </div>
            <div className="flex">
              <span className="w-24 shrink-0 font-bold text-slate-500 text-[8pt]">Departure</span>
              <span className="mr-3 text-slate-400">:</span>
              <span className="flex-1 font-bold text-slate-900">{formatIndonesianDate(invoice.stay.checkOut)}</span>
            </div>
          </div>
        </div>
      </div>

      {/* 5. Main Billing Table - Reduced row padding */}
      <div className="flex-1">
        <table className="w-full text-left border-collapse border border-slate-300">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-300">
              <th className="py-2 px-4 text-[7.5pt] font-black uppercase border-r border-slate-300">DESCRIPTION</th>
              <th className="py-2 px-4 text-[7.5pt] font-black uppercase text-center border-r border-slate-300">QTY</th>
              <th className="py-2 px-4 text-[7.5pt] font-black uppercase text-center border-r border-slate-300">NIGHTS</th>
              <th className="py-2 px-4 text-[7.5pt] font-black uppercase text-right border-r border-slate-300">UNIT PRICE</th>
              <th className="py-2 px-4 text-[7.5pt] font-black uppercase text-right">TOTAL AMOUNT</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200">
            {invoice.items.map((item) => (
              <tr key={item.id} className="text-[9pt]">
                <td className="py-2 px-4 font-bold text-slate-900 uppercase border-r border-slate-300">{item.description}</td>
                <td className="py-2 px-4 text-center border-r border-slate-300">{item.quantity}</td>
                <td className="py-2 px-4 text-center border-r border-slate-300">{item.nights}</td>
                <td className="py-2 px-4 text-right border-r border-slate-300">Rp {formatCurrency(item.unitPrice)}</td>
                <td className="py-2 px-4 font-black text-slate-900 text-right">Rp {formatCurrency(item.quantity * item.nights * item.unitPrice)}</td>
              </tr>
            ))}
            {[...Array(Math.max(0, 3 - invoice.items.length))].map((_, i) => (
              <tr key={`empty-${i}`} className="h-8">
                <td className="border-r border-slate-300"></td>
                <td className="border-r border-slate-300"></td>
                <td className="border-r border-slate-300"></td>
                <td className="border-r border-slate-300"></td>
                <td></td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* 6. Totals & Summaries - Reduced margin and tightened internal spacing */}
        <div className="mt-6 flex justify-between gap-10">
          <div className="flex-1">
            {/* Payment Methods */}
            {paymentMethods.length > 0 && (
              <div className="mb-3">
                <p className="text-[7pt] font-black text-slate-400 uppercase tracking-widest mb-1.5 border-b border-slate-100 pb-1">METODE PEMBAYARAN</p>
                <div className="flex flex-wrap gap-1.5">
                  {paymentMethods.map(method => (
                    <span key={method} className="text-[8pt] font-bold text-slate-900 bg-slate-100 border border-slate-200 px-2 py-0.5 rounded-sm uppercase">
                      {method}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {/* Bank Account Info */}
            {hotel.bankInfo && (
              <div className="mb-4">
                <p className="text-[7pt] font-black text-slate-400 uppercase tracking-widest mb-1 border-b border-slate-100 pb-1">REKENING PEMBAYARAN</p>
                <p className="text-[8.5pt] font-bold text-slate-800 uppercase leading-tight">
                  {hotel.bankInfo}
                </p>
              </div>
            )}

            {invoice.remarks && (
              <div className="bg-slate-50/50 p-3 border border-slate-200 rounded-sm">
                <p className="text-[7pt] font-black text-slate-400 uppercase tracking-widest mb-1">NOTES / REMARKS</p>
                <p className="text-[8.5pt] text-slate-700 italic leading-snug whitespace-pre-wrap">{invoice.remarks}</p>
              </div>
            )}
          </div>

          <div className="w-[280px] shrink-0 border border-slate-300 rounded-sm overflow-hidden h-fit">
            <div className="flex justify-between px-3 py-1.5 text-[8.5pt] border-b border-slate-100">
              <span className="font-bold text-slate-500 uppercase">SUBTOTAL</span>
              <span className="font-bold">Rp {formatCurrency(subtotal)}</span>
            </div>
            {invoice.discount > 0 && (
              <div className="flex justify-between px-3 py-1.5 text-[8.5pt] border-b border-slate-100">
                <span className="font-bold text-slate-500 uppercase">ADJUSTMENT</span>
                <span className="font-bold text-rose-600">- Rp {formatCurrency(invoice.discount)}</span>
              </div>
            )}
            <div className="flex justify-between px-3 py-1.5 text-[8.5pt] border-b border-slate-100 text-emerald-700 bg-emerald-50/20">
              <span className="font-bold uppercase">PAID / DEPOSIT</span>
              <span className="font-bold">- Rp {formatCurrency(totalPaid)}</span>
            </div>
            <div className="flex justify-between px-3 py-1.5 text-[8.5pt] border-b border-slate-100">
              <span className="font-bold text-slate-500 uppercase">Total Bayar</span>
              <span className="font-bold text-slate-900">Rp {formatCurrency(totalCharge)}</span>
            </div>
            <div className="flex justify-between px-3 py-3 bg-slate-900 text-white">
              <span className="text-[9pt] font-black uppercase tracking-widest">BALANCE DUE</span>
              <span className="text-[12pt] font-black">Rp {formatCurrency(balanceDue)}</span>
            </div>
          </div>
        </div>
      </div>

      {/* 7. Footer Signatures - Reduced margin top and gap */}
      <div className="mt-10 grid grid-cols-2 gap-20">
        <div className="text-center">
          <p className="text-[8pt] font-bold text-slate-400 uppercase tracking-[0.3em] mb-16">GUEST SIGNATURE</p>
          <div className="border-b border-slate-400 w-52 mx-auto mb-1"></div>
          <p className="text-[9pt] font-bold uppercase">{invoice.guest.name || 'GUEST NAME'}</p>
        </div>
        <div className="text-center relative">
          <p className="text-[8pt] font-bold text-slate-400 uppercase tracking-[0.3em] mb-16">RECEPTIONIST / CASHIER</p>

          <div className="absolute top-[35%] left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-20 pointer-events-none flex items-center justify-center overflow-visible hide-on-physical-print">
            {hotel.signature && (
               <img src={hotel.signature} alt="Sign" className="absolute w-32 object-contain opacity-95 z-10 translate-y-2" />
            )}
            {hotel.stamp && (
               <img src={hotel.stamp} alt="Stamp" className="absolute w-32 object-contain opacity-30 rotate-[-12deg] -translate-x-8 -translate-y-2 mix-blend-multiply" />
            )}
          </div>

          <div className="border-b border-slate-400 w-52 mx-auto mb-1"></div>
          <p className="text-[9pt] font-bold uppercase">{invoice.cashierName || 'STAFF NAME'}</p>
        </div>
      </div>

      {/* 8. Final Footer Branding - Reduced padding */}
      <div className="mt-auto pt-4 text-center border-t border-slate-100">
        <p className="text-slate-400 text-[7.5pt] font-bold uppercase tracking-[0.6em] mb-0.5">
          Thank you for choosing {hotel.name}
        </p>
        <p className="text-slate-300 text-[6.5pt] uppercase tracking-tighter">
          Generated: {new Date().toLocaleString('id-ID', { dateStyle: 'long', timeStyle: 'short' })}
        </p>
      </div>
    </div>
  );
};

export type UserRole = 'super-admin' | 'admin' | 'manager' | 'receptionist';

export interface UserProfile {
  id: string;
  email: string;
  role: UserRole;
  fullName?: string;
  updated_at?: string;
}

export interface HotelSettings {
  name: string;
  address: string;
  phone: string;
  email: string;
  website: string;
  logo: string;
  bankInfo?: string;
  signature?: string;
  stamp?: string;
  defaultTaxRate: number;
  supabaseUrl?: string;
  supabaseAnonKey?: string;
  settingsPin?: string;
}

export interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  nights: number;
  unitPrice: number;
  total: number;
}

export interface Payment {
  id: string;
  date: string;
  method: string;
  amount: number;
}

export interface GuestInfo {
  name: string;
  email: string;
  phone: string;
  address: string;
}

export interface StayDetails {
  roomNumber: string;
  roomType: string;
  guestType: string; 
  checkIn: string;
  checkOut: string;
  guestsCount: number;
}

export interface Invoice {
  id: string;
  invoiceNumber: string;
  date: string;
  guest: GuestInfo;
  stay: StayDetails;
  items: InvoiceItem[];
  payments: Payment[];
  taxRate: number;
  discount: number;
  status: 'draft' | 'paid' | 'cancelled';
  notes: string;
  remarks?: string;
  hotelSnap?: HotelSettings;
  cashierName?: string;
}

export type ViewMode = 'list' | 'create' | 'view' | 'settings' | 'villa';

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings, UserProfile } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { SettingsPage } from './components/SettingsPage';
import { Auth } from './components/Auth';
import { MobileDashboardList } from './components/mobile/MobileDashboardList';
import { DesktopDashboardTable } from './components/desktop/DesktopDashboardTable';
import { MobileInvoiceForm } from './components/mobile/MobileInvoiceForm';
import { DesktopInvoiceForm } from './components/desktop/DesktopInvoiceForm';
import { ROOM_TYPES, GUEST_TYPES, HOTEL_INFO, TAX_RATE } from './constants';
import { 
  fetchInvoicesFromSupabase, 
  upsertInvoiceToSupabase, 
  saveSettingsToSupabase, 
  fetchSettingsFromSupabase,
  onAuthStateChange,
  signOut,
  getCurrentUserProfile
} from './services/supabaseService';
import { generatePersonalizedNote } from './services/geminiService';

declare var html2pdf: any;

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], guestType: GUEST_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const SUPER_ADMIN_EMAILS = ['hotelpangandaranblueorchid@gmail.com', 'rifkiandrean@gmail.com'];

const App: React.FC = () => {
  const [session, setSession] = useState<any>(null);
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);

  const [showPinModal, setShowPinModal] = useState(false);
  const [pinValue, setPinValue] = useState('');
  const [pinError, setPinError] = useState(false);

  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const [settings, setSettings] = useState<HotelSettings>({
    ...HOTEL_INFO,
    defaultTaxRate: TAX_RATE,
    settingsPin: "1234"
  });

  useEffect(() => {
    const { data: { subscription } } = onAuthStateChange(async (newSession) => {
      setSession(newSession);
      if (newSession?.user) {
        const profile = await getCurrentUserProfile(newSession.user.id);
        const email = newSession.user.email?.toLowerCase();

        if (email && SUPER_ADMIN_EMAILS.includes(email)) {
          setUserProfile({ 
            id: newSession.user.id, 
            email: newSession.user.email, 
            role: 'super-admin' 
          });
        } else {
          setUserProfile(profile);
        }
      } else {
        setUserProfile(null);
        setViewMode('list');
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  const loadCloudSettings = useCallback(async () => {
    if (!session) return;
    setSyncStatus('syncing');
    try {
      const cloudSettings = await fetchSettingsFromSupabase(settings);
      if (cloudSettings) {
        setSettings(prev => ({ 
          ...prev, 
          ...cloudSettings,
          supabaseUrl: HOTEL_INFO.supabaseUrl,
          supabaseAnonKey: HOTEL_INFO.supabaseAnonKey
        }));
        setSyncStatus('success');
      }
    } catch (error) {
      console.error("Failed to load cloud settings:", error);
      setSyncStatus('error');
    } finally {
      setTimeout(() => setSyncStatus('idle'), 2000);
    }
  }, [session]);

  useEffect(() => {
    if (session) {
      loadCloudSettings();
    }
  }, [session, loadCloudSettings]);

  const syncFromSupabase = useCallback(async () => {
    if (!session) return;
    setSyncStatus('syncing');
    try {
      const cloudInvoices = await fetchInvoicesFromSupabase(settings);
      setInvoices(cloudInvoices);
      setSyncStatus('success');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  }, [session, settings]);

  useEffect(() => {
    if (viewMode === 'list' && session) {
      syncFromSupabase();
    }
  }, [viewMode, syncFromSupabase, session]);

  const handleSaveSettings = async (newSettings: HotelSettings) => {
    if (session) {
      setSyncStatus('syncing');
      const success = await saveSettingsToSupabase(newSettings);
      if (success) {
        setSettings(newSettings);
        setSyncStatus('success');
        alert('Pengaturan berhasil disimpan ke cloud!');
      } else {
        setSyncStatus('error');
        alert('Gagal menyimpan ke cloud. Periksa koneksi atau database.');
        loadCloudSettings(); 
      }
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  };

  const handleLogout = async () => {
    if (confirm('Apakah Anda yakin ingin keluar?')) {
      try {
        await signOut();
        setSession(null);
        setUserProfile(null);
        setViewMode('list');
      } catch (err) {
        console.error("Error during sign out:", err);
      }
    }
  };

  const calculateSubtotal = (inv: Invoice) => inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
  const calculateTotal = (inv: Invoice) => calculateSubtotal(inv) - inv.discount;
  const calculatePayments = (inv: Invoice) => inv.payments.reduce((sum, p) => sum + p.amount, 0);
  const calculateBalance = (inv: Invoice) => calculateTotal(inv) - calculatePayments(inv);
  const formatCurrency = (val: number) => val.toLocaleString('id-ID');

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    const isDuplicate = invoices.some(inv => 
      inv.invoiceNumber === currentInvoice.invoiceNumber && inv.id !== currentInvoice.id
    );

    if (isDuplicate) {
      alert(`Gagal menyimpan: Nomor Invoice "${currentInvoice.invoiceNumber}" sudah digunakan oleh data lain. Silakan perbarui nomor invoice.`);
      return;
    }

    const finalizedInvoice = { ...currentInvoice, hotelSnap: settings };

    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');

    if (session) {
      setSyncStatus('syncing');
      const success = await upsertInvoiceToSupabase(finalizedInvoice, settings);
      if (success) {
        setSyncStatus('success');
        syncFromSupabase();
      } else {
        setSyncStatus('error');
        alert('Gagal menyimpan invoice ke cloud.');
      }
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  };

  const handleGenerateAINote = async () => {
    if (!currentInvoice || !currentInvoice.guest.name) return;
    setIsGeneratingNote(true);
    try {
      const aiNote = await generatePersonalizedNote(currentInvoice);
      setCurrentInvoice({ ...currentInvoice, remarks: aiNote });
    } catch (error) {
      console.error("Failed to generate AI note:", error);
    } finally {
      setIsGeneratingNote(false);
    }
  };

  const downloadPDF = () => {
    if (!currentInvoice) return;
    const element = document.getElementById('invoice-content');
    if (!element) return;

    const opt = {
      margin: 0,
      filename: `Invoice ${currentInvoice.invoiceNumber} - ${currentInvoice.guest.name || 'GUEST'}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2, 
        useCORS: true, 
        letterRendering: true, 
        backgroundColor: '#FFFFFF',
        scrollY: 0, 
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    const container = document.querySelector('.invoice-preview-container');
    if (container) container.scrollTop = 0;

    html2pdf().set(opt).from(element).save();
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      items: currentInvoice.items.map(item => item.id === id ? { ...item, ...updates } : item)
    });
  };

  const handleDeleteItem = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      items: currentInvoice.items.filter(i => i.id !== id)
    });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      payments: currentInvoice.payments.map(p => p.id === id ? { ...p, ...updates } : p)
    });
  };

  const handleDeletePayment = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      payments: currentInvoice.payments.filter(p => p.id !== id)
    });
  };

  const createNewInvoice = () => {
    const id = Math.random().toString(36).substr(2, 9);
    const lastCashier = invoices.length > 0 ? invoices[0].cashierName : '';
    const currentYear = new Date().getFullYear();
    const prefix = `INV-${currentYear}-`;
    const sequenceNumbers = invoices
      .filter(inv => inv.invoiceNumber.startsWith(prefix))
      .map(inv => parseInt(inv.invoiceNumber.split('-').pop() || '0', 10));
    const nextSequence = (sequenceNumbers.length > 0 ? Math.max(...sequenceNumbers) : 0) + 1;

    setCurrentInvoice({
      id,
      invoiceNumber: `${prefix}${nextSequence.toString().padStart(4, '0')}`,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [{ id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }],
      payments: [],
      taxRate: 0, discount: 0, status: 'draft', notes: '', remarks: '', hotelSnap: settings,
      cashierName: lastCashier || ''
    });
    setViewMode('create');
  };

  const filteredInvoices = invoices.filter(inv => {
    const matchesSearch = 
      inv.guest.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      inv.invoiceNumber.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesStatus = statusFilter === 'all' || inv.status === statusFilter;

    const matchesStartDate = !startDate || inv.date >= startDate;
    const matchesEndDate = !endDate || inv.date <= endDate;

    return matchesSearch && matchesStatus && matchesStartDate && matchesEndDate;
  });

  const handleSettingsClick = () => {
    setPinValue('');
    setPinError(false);
    setShowPinModal(true);
  };

  const handlePinSubmit = (val: string) => {
    const targetPin = settings.settingsPin || "1234";
    if (val === targetPin) {
      setShowPinModal(false);
      setViewMode('settings');
    } else {
      setPinError(true);
      setPinValue('');
      setTimeout(() => setPinError(false), 500);
    }
  };

  const handlePinDigit = (digit: string) => {
    const newVal = pinValue + digit;
    if (newVal.length <= 4) {
      setPinValue(newVal);
      if (newVal.length === 4) {
        setTimeout(() => handlePinSubmit(newVal), 100);
      }
    }
  };

  if (!session) return <Auth hotelName={settings.name} />;

  const invoiceCalculations = currentInvoice ? {
    subtotal: calculateSubtotal(currentInvoice),
    total: calculateTotal(currentInvoice),
    paid: calculatePayments(currentInvoice),
    balance: calculateBalance(currentInvoice)
  } : { subtotal: 0, total: 0, paid: 0, balance: 0 };

  return (
    <div className="h-screen bg-slate-50 flex flex-col overflow-hidden">
      <header className="bg-white border-b border-slate-200 h-14 shrink-0 flex items-center z-50 no-print">
        <div className="max-w-[1600px] w-full mx-auto px-4 lg:px-6 flex justify-between items-center">
          <div className="flex items-center gap-2 lg:gap-6">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setViewMode('list')}>
              <div className="bg-indigo-600 p-1.5 rounded-lg shrink-0">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
              </div>
              <div className="flex items-center gap-2 lg:gap-3">
                <h1 className="text-base lg:text-lg font-black text-slate-900 hidden xs:block tracking-tighter">HotelFlow</h1>
                <div className="w-px h-6 bg-slate-200 hidden md:block"></div>
                <h2 className="text-[11px] lg:text-xs font-bold text-indigo-600 uppercase tracking-widest hidden md:block line-clamp-1 max-w-[200px] lg:max-w-none">
                  {settings.name}
                </h2>
              </div>
            </div>
            <nav className="flex items-center gap-0.5 lg:gap-1">
              <button onClick={() => setViewMode('list')} className={`px-2 lg:px-4 py-1.5 rounded-lg text-[10px] lg:text-xs font-bold ${viewMode === 'list' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Beranda</button>
              <button onClick={() => setViewMode('villa')} className={`px-2 lg:px-4 py-1.5 rounded-lg text-[10px] lg:text-xs font-bold ${viewMode === 'villa' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Villa</button>
