                  {settings.name}
                </h2>
              </div>
            </div>
            <nav className="flex items-center gap-0.5 lg:gap-1">
              <button onClick={() => setViewMode('list')} className={`px-2 lg:px-4 py-1.5 rounded-lg text-[10px] lg:text-xs font-bold ${viewMode === 'list' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Hotel & Cottage</button>
              <button onClick={() => setViewMode('villa')} className={`px-2 lg:px-4 py-1.5 rounded-lg text-[10px] lg:text-xs font-bold ${viewMode === 'villa' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Villa</button>
              <button onClick={handleSettingsClick} className={`px-2 lg:px-4 py-1.5 rounded-lg text-[10px] lg:text-xs font-bold ${viewMode === 'settings' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Settings</button>
            </nav>
          </div>

          <div className="flex items-center gap-2 lg:gap-4">
            {syncStatus !== 'idle' && (
              <div className={`px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 ${
                syncStatus === 'syncing' ? 'bg-slate-100 text-slate-500' :
                syncStatus === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'
