              {invoice.payments.map(p => <PaymentRow key={p.id} payment={p} onUpdate={onUpdatePayment} onDelete={onDeletePayment} />) || <p className="text-center py-4 text-slate-400 text-[10px] italic">Belum ada pembayaran.</p>}
            </div>
