    const nextSequence = (sequenceNumbers.length > 0 ? Math.max(...sequenceNumbers) : 0) + 1;

    setCurrentInvoice({
      id,
      category: activeCategory,
      invoiceNumber: `${prefix}${nextSequence.toString().padStart(4, '0')}`,
      date: today,
      guest: { ...INITIAL_GUEST },
