                      <input 
                        type="text" 
                        placeholder="Cari nama, company, atau invoice..." 
                        className="w-full pl-9 pr-4 py-2 border border-slate-200 rounded-xl text-sm outline-none focus:ring-1 focus:ring-indigo-500 transition-all"
