                                   <option value="super-admin">Locked</option>
                                ) : (
                                  <>
                                    <option value="receptionist">Receptionist</option>
                                    <option value="manager">Manager</option>
                                    <option value="admin">Admin</option>
                                  </>
                                )}
                              </select>
                            </td>
                            {canManageSubscriptions && (
                              <>
                                <td className="px-4 py-4">
                                  {!isSelf ? (
                                    <select 
                                      value={profile.subscription_status || 'inactive'} 
                                      onChange={(e) => handleUpdateSubscription(profile.id, e.target.value as 'active' | 'inactive')}
                                      className={`text-[10px] font-bold border rounded px-2 py-1 outline-none w-24 uppercase ${
                                        profile.subscription_status === 'active' 
                                          ? 'border-emerald-200 bg-emerald-50 text-emerald-600' 
                                          : 'border-slate-200 bg-slate-50 text-slate-500'
                                      }`}
                                    >
                                      <option value="active">Active</option>
                                      <option value="inactive">Inactive</option>
                                    </select>
                                  ) : (
