                            <td className="px-4 py-4">
                              <select 
                                onChange={(e) => handleChangeRole(profile.id, e.target.value as UserRole)}
                                value={profile.role}
                                disabled={isSuperAdmin}
                                className={`text-[10px] font-bold border border-slate-200 rounded px-2 py-1 outline-none bg-white w-32 ${isSuperAdmin ? 'opacity-50 cursor-not-allowed text-slate-300' : 'text-slate-500'}`}
                              >
                                {isSuperAdmin ? (
                                   <option value="super-admin">Locked</option>
                                ) : (
                                  <>
                                    <option value="receptionist">Receptionist</option>
                                    <option value="manager">Manager</option>
                                    <option value="admin">Admin</option>
                                  </>
                                )}
                              </select>
                            </td>
                            {canManageSubscriptions && (
                              <>
                                <td className="px-4 py-4">
                                  {!isSelf ? (
                                    <select 
                                      value={profile.subscription_status || 'inactive'} 
                                      onChange={(e) => handleUpdateSubscription(profile.id, e.target.value as 'active' | 'inactive')}
                                      className={`text-[10px] font-bold border rounded px-2 py-1 outline-none w-24 uppercase ${
                                        profile.subscription_status === 'active' 
                                          ? 'border-emerald-200 bg-emerald-50 text-emerald-600' 
                                          : 'border-slate-200 bg-slate-50 text-slate-500'
                                      }`}
                                    >
                                      <option value="active">Active</option>
                                      <option value="inactive">Inactive</option>
                                    </select>
                                  ) : (
                                    <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded">LIFETIME</span>
                                  )}
                                </td>
                                <td className="px-4 py-4">
                                  {!isSelf && (
                                    <input 
                                      type="date"
                                      value={profile.subscription_end_date ? new Date(profile.subscription_end_date).toISOString().split('T')[0] : ''}
                                      onChange={(e) => handleUpdateSubscription(profile.id, profile.subscription_status || 'inactive', e.target.value)}
                                      className="text-[10px] border border-slate-200 rounded px-2 py-1 w-32"
                                    />
                                  )}
                                </td>
                              </>
                            )}
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
               </div>
            </section>
          </div>
        )}
      </div>
    </div>
  );
};

